// Send gate for the assistant's push notifications.
//
// Promo policy: at most 3 promos per customer per local calendar day
// (midnight to midnight in the customer's time zone), and at least 2 hours
// between two promos to the same customer.
// Security alerts are transactional: they are never limited and never counted.
//
// request() both checks and records: an allowed result means the caller sends
// now. cancel(id) removes the record when the push never left the system, so
// it no longer counts toward the cap or the spacing rule.

const MAX_PROMOS_PER_DAY = 3;
const MIN_GAP_MS = 2 * 60 * 60 * 1000;

const formatters = new Map();

// Throws RangeError for an invalid IANA name.
function formatterFor(timeZone) {
  let f = formatters.get(timeZone);
  if (!f) {
    f = new Intl.DateTimeFormat('en-CA', {
      timeZone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
    });
    formatters.set(timeZone, f);
  }
  return f;
}

// Local calendar date such as "2026-03-08" for the instant in that zone.
function localDay(timeMs, timeZone) {
  return formatterFor(timeZone).format(timeMs);
}

export function createGate() {
  let nextId = 1;
  // userId -> array of { id, t } for promos that were allowed and not cancelled
  const promosByUser = new Map();
  // id -> userId, for promo sends only
  const promoOwner = new Map();

  const deny = (rule) => ({ allowed: false, rule, id: null });
  const allow = () => ({ allowed: true, rule: '', id: `send-${nextId++}` });

  function request({ userId, timeZone, category, now }) {
    if (category === 'security') return allow();
    if (category !== 'promo') return deny('unknown-category');

    const t = now instanceof Date ? now.getTime() : NaN;
    if (!Number.isFinite(t)) return deny('invalid-time');

    let today;
    try {
      today = localDay(t, timeZone);
    } catch {
      return deny('invalid-time-zone');
    }

    const list = promosByUser.get(userId) ?? [];

    let sameDay = 0;
    for (const p of list) {
      if (localDay(p.t, timeZone) === today) sameDay++;
    }
    if (sameDay >= MAX_PROMOS_PER_DAY) return deny('daily-cap');

    for (const p of list) {
      if (Math.abs(t - p.t) < MIN_GAP_MS) return deny('min-gap');
    }

    const result = allow();
    list.push({ id: result.id, t });
    promosByUser.set(userId, list);
    promoOwner.set(result.id, userId);
    return result;
  }

  function cancel(id) {
    const userId = promoOwner.get(id);
    if (userId === undefined) return;
    promoOwner.delete(id);
    const list = promosByUser.get(userId);
    if (!list) return;
    const i = list.findIndex((p) => p.id === id);
    if (i !== -1) list.splice(i, 1);
    if (list.length === 0) promosByUser.delete(userId);
  }

  return { request, cancel };
}

import assert from 'node:assert/strict';
import { createGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round8-final/d-sonnet/work/knock-inv-d2-1/bot.mjs';

const d = (s) => new Date(s);
const LA = 'America/Los_Angeles';
const req = (g, o) => g.request({ userId: 'u', timeZone: LA, category: 'promo', ...o });

// cap 3, gap 2h; LA is UTC-7 in June, so local day = 07:00Z to 07:00Z
{
  const g = createGate();
  const a = req(g, { now: d('2026-06-10T08:00:00Z') });
  assert.ok(a.allowed && a.rule === '' && a.id);
  assert.equal(req(g, { now: d('2026-06-10T09:59:59Z') }).rule, 'min-gap');
  assert.ok(req(g, { now: d('2026-06-10T10:00:00Z') }).allowed);
  assert.ok(req(g, { now: d('2026-06-10T12:00:00Z') }).allowed);
  const r = req(g, { now: d('2026-06-10T14:00:00Z') });
  assert.deepEqual(r, { allowed: false, rule: 'daily-cap', id: null });
  // next local midnight (07:00Z) resets, even though only 2h+ later
  assert.ok(req(g, { now: d('2026-06-11T07:00:00Z') }).allowed);
  // security unaffected and not counted
  assert.ok(g.request({ userId: 'u', timeZone: LA, category: 'security', now: d('2026-06-10T14:00:00Z') }).allowed);
}
// same instants, different zone: Berlin (UTC+2) day boundary at 22:00Z
{
  const g = createGate();
  const b = (now) => g.request({ userId: 'u', timeZone: 'Europe/Berlin', category: 'promo', now: d(now) });
  assert.ok(b('2026-06-10T10:00:00Z').allowed);
  assert.ok(b('2026-06-10T12:00:00Z').allowed);
  assert.ok(b('2026-06-10T14:00:00Z').allowed);
  assert.equal(b('2026-06-10T16:00:00Z').rule, 'daily-cap');
  assert.ok(b('2026-06-10T22:00:00Z').allowed); // 00:00 local next day
}
// cancel frees cap and gap; idempotent; unknown ids ignored
{
  const g = createGate();
  const a = req(g, { now: d('2026-06-10T08:00:00Z') });
  assert.equal(req(g, { now: d('2026-06-10T09:00:00Z') }).rule, 'min-gap');
  g.cancel(a.id); g.cancel(a.id); g.cancel('nope');
  assert.ok(req(g, { now: d('2026-06-10T09:00:00Z') }).allowed);
  const s = g.request({ userId: 'u', timeZone: LA, category: 'security', now: d('2026-06-10T09:00:00Z') });
  g.cancel(s.id);
}
// users independent; DST day (LA 2026-03-08 is 23h long)
{
  const g = createGate();
  const o = { timeZone: LA, category: 'promo' };
  assert.ok(g.request({ userId: 'a', ...o, now: d('2026-03-08T08:00:00Z') }).allowed); // 00:00 PST
  assert.ok(g.request({ userId: 'b', ...o, now: d('2026-03-08T08:00:00Z') }).allowed);
  assert.ok(g.request({ userId: 'a', ...o, now: d('2026-03-08T10:00:00Z') }).allowed);
  assert.ok(g.request({ userId: 'a', ...o, now: d('2026-03-08T12:00:00Z') }).allowed);
  assert.equal(g.request({ userId: 'a', ...o, now: d('2026-03-08T14:00:00Z') }).rule, 'daily-cap');
  // 07:00Z Mar 9 = 00:00 PDT
  assert.ok(g.request({ userId: 'a', ...o, now: d('2026-03-09T07:00:00Z') }).allowed);
}
// bad input
{
  const g = createGate();
  assert.equal(g.request({ userId: 'u', timeZone: 'Nope/Zone', category: 'promo', now: d('2026-06-10T08:00:00Z') }).rule, 'invalid-time-zone');
  assert.equal(g.request({ userId: 'u', timeZone: LA, category: 'x', now: d('2026-06-10T08:00:00Z') }).rule, 'unknown-category');
}
console.log('all ok');
